import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const group = new ctx.THREE.Group();
  group.userData.handlers = {};

  // Store cleanup callbacks
  const disposables = [];

  // Load texture and create plane
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  const planeGeom = new ctx.THREE.PlaneGeometry(1.6, 1); // aspect 512/320 = 1.6
  const material = new MeshBasicNodeMaterial();
  material.transparent = true;
  material.depthWrite = false;
  const plane = new ctx.THREE.Mesh(planeGeom, material);
  group.add(plane);

  texturePromise.then((tex) => {
    material.map = tex;
    material.needsUpdate = true;
    disposables.push(() => tex.dispose());
  });

  // Create text objects
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  items.forEach((item) => {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 39,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'center',
      maxWidthPx: 512,
    });
    group.add(txt);
    disposables.push(() => {
      if (txt.geometry) txt.geometry.dispose();
      if (txt.material) txt.material.dispose();
    });
  });

  // Apply cinematic primitives
  const primitiveInstances = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((p) => {
      const prim = ctx.primitives[p.name](group, p.params);
      primitiveInstances.push(prim);
    });
  }

  // Cleanup routine
  group.userData.cleanup = () => {
    // Dispose material and geometry
    material.dispose();
    planeGeom.dispose();

    // Dispose texture
    texturePromise.then((tex) => tex.dispose()).catch(() => {});

    // Dispose primitives
    primitiveInstances.forEach((prim) => {
      if (prim.cleanup) prim.cleanup();
      if (prim.timeline && prim.timeline.kill) prim.timeline.kill();
    });

    // Run stored disposables
    disposables.forEach((fn) => fn());
  };

  return group;
}
